import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const router = express.Router();
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 5 * 1024 * 1024 } });

interface ResumeAnalysisRequest extends Request {
  file?: Express.Multer.File;
  body: {
    jobDescription?: string;
  };
}

function extractKeywords(text: string): string[] {
  const stopwords = new Set(['and', 'the', 'to', 'a', 'of', 'in', 'for', 'is', 'on', 'that', 'by', 'this', 'with', 'i', 'you', 'it'] );
  const words = text.toLowerCase().replace(/[^a-z0-9\+\#\.]/g, ' ').split(/\s+/);
  const keywords = words.filter(w => w.length > 2 && !stopwords.has(w));
  return Array.from(new Set(keywords));
}

router.post('/api/parse-resume', upload.single('resume'), async (req: ResumeAnalysisRequest, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No PDF resume file provided.' });
      return;
    }
    const { jobDescription = '' } = req.body;
    const pdfData = await pdfParse(req.file.buffer);
    const resumeText = pdfData.text;

    const resumeKeywords = extractKeywords(resumeText);
    const jobKeywords = extractKeywords(jobDescription);

    const matchedKeywords = jobKeywords.filter(kw => resumeKeywords.includes(kw));
    const missingKeywords = jobKeywords.filter(kw => !resumeKeywords.includes(kw));

    const score = jobKeywords.length > 0 
      ? Math.round((matchedKeywords.length / jobKeywords.length) * 100) 
      : 0;

    res.json({
      score,
      totalResumeWords: resumeKeywords.length,
      matchedKeywords,
      missingKeywords,
      extractedTextSnippet: resumeText.substring(0, 300) + '...'
    });
  } catch (error) {
    console.error('PDF Parsing Error:', error);
    res.status(500).json({ error: 'Failed to parse PDF resume.' });
  }
});

export default router;

import React, { useState, ChangeEvent, FormEvent } from 'react';

interface AnalysisResult {
  score: number;
  matchedKeywords: string[];
  missingKeywords: string[];
  extractedTextSnippet: string;
}

export const MatchScoreDashboard: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [jobDesc, setJobDesc] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [result, setResult] = useState<AnalysisResult | null>(null);

  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!file || !jobDesc) return;

    setLoading(true);
    const formData = new FormData();
    formData.append('resume', file);
    formData.append('jobDescription', jobDesc);

    try {
      const response = await fetch('/api/parse-resume', {
        method: 'POST',
        body: formData,
      });
      const data = await response.json();
      setResult(data);
    } catch (err) {
      console.error('Error scanning resume:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6 bg-slate-900 text-slate-100 rounded-xl shadow-2xl">
      <h1 className="text-3xl font-extrabold mb-6 text-indigo-400">Aegis AI Resume Keyword Scanner</h1>
      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="border-2 border-dashed border-slate-700 p-6 rounded-lg text-center bg-slate-800/50">
            <input type="file" accept=".pdf" onChange={handleFileChange} className="hidden" id="resume-upload" />
            <label htmlFor="resume-upload" className="cursor-pointer block">
              <span className="text-indigo-300 font-semibold">{file ? file.name : 'Click to upload PDF resume'}</span>
              <p className="text-xs text-slate-400 mt-1">PDF up to 5MB</p>
            </label>
          </div>
          <textarea
            value={jobDesc}
            onChange={(e) => setJobDesc(e.target.value)}
            placeholder="Paste target job description here..."
            className="w-full h-32 p-3 bg-slate-800 border border-slate-700 rounded-lg text-sm text-slate-200 focus:outline-none focus:border-indigo-500"
          />
        </div>
        <button
          type="submit"
          disabled={loading || !file || !jobDesc}
          className="w-full py-3 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-50 font-bold rounded-lg transition duration-200"
        >
          {loading ? 'Scanning Keywords...' : 'Run AI Match Analysis'}
        </button>
      </form>

      {result && (
        <div className="mt-10 grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="flex flex-col items-center justify-center bg-slate-800 p-6 rounded-xl border border-slate-700">
            <div className="text-5xl font-black text-indigo-400 mb-2">{result.score}%</div>
            <div className="text-sm uppercase tracking-wider text-slate-400 font-semibold">Match Score</div>
          </div>
          <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 md:col-span-2 space-y-4">
            <div>
              <h3 className="text-sm font-bold text-emerald-400 uppercase mb-2">Matched Keywords ({result.matchedKeywords.length})</h3>
              <div className="flex flex-wrap gap-2">
                {result.matchedKeywords.map((kw, i) => (
                  <span key={i} className="px-2.5 py-1 bg-emerald-950 text-emerald-300 text-xs font-medium rounded-full border border-emerald-800">{kw}</span>
                ))}
              </div>
            </div>
            <div>
              <h3 className="text-sm font-bold text-rose-400 uppercase mb-2">Missing Keywords ({result.missingKeywords.length})</h3>
              <div className="flex flex-wrap gap-2">
                {result.missingKeywords.map((kw, i) => (
                  <span key={i} className="px-2.5 py-1 bg-rose-950 text-rose-300 text-xs font-medium rounded-full border border-rose-800">{kw}</span>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
